<template><view class="page"><text @click="back">‹ {{ tr('Back') }}</text><view>{{ tr('Change Password') }}</view><input v-model="oldPassword" password :placeholder="tr('Current password (leave empty if not set)')" /><input v-model="newPassword" password :placeholder="tr('New Password')" /><input v-model="confirmation" password :placeholder="tr('Confirm Password')" /><button @click="save" :disabled="busy">{{ tr('Save') }}</button></view></template><script>
import {getAuthUrl} from '@/config/api.js';
export default {data:()=>({oldPassword:'',newPassword:'',confirmation:'',busy:false}),methods:{back(){uni.navigateBack();},save(){if(this.newPassword.length<6||this.newPassword!==this.confirmation){uni.showToast({title:this.tr('Use at least six characters and matching passwords'),icon:'none'});return;}this.busy=true;uni.request({url:getAuthUrl('changePassword'),method:'POST',data:{oldPassword:this.oldPassword,newPassword:this.newPassword},success:r=>{uni.showToast({title:this.tr(r.data.errcode===0?'Saved':r.data.msg),icon:'none'});if(r.data.errcode===0){this.oldPassword='';this.newPassword='';this.confirmation='';}},complete:()=>{this.busy=false;}});}}};
</script><style scoped>.page{padding:40rpx;}input{padding:24rpx;border:1px solid #ddd;margin:24rpx 0;}button{padding:24rpx;background:#e0e7ff;}</style>